const xml = $input.first().json.body || '';
const results = [];

// Parse RSS items from XML
const itemPattern = /<item>([\s\S]*?)<\/item>/gi;
let itemMatch;

while ((itemMatch = itemPattern.exec(xml)) !== null) {
  const itemXml = itemMatch[1];

  const titleMatch = itemXml.match(/<title><!\[CDATA\[([^\]]*?)\]\]>|<title>([^<]*?)<\/title>/);
  const linkMatch = itemXml.match(/<link>([^<]*?)<\/link>/);
  const pubDateMatch = itemXml.match(/<pubDate>([^<]*?)<\/pubDate>/);
  const descMatch = itemXml.match(/<description><!\[CDATA\[([^\]]*?)\]\]>|<description>([^<]*?)<\/description>/);

  const title = titleMatch ? (titleMatch[1] || titleMatch[2] || '').trim() : 'Untitled';
  const link = linkMatch ? linkMatch[1].trim() : '';
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : '';
  const description = descMatch ? (descMatch[1] || descMatch[2] || '').trim() : '';

  if (title && link) {
    results.push({
      json: {
        title,
        link,
        pub_date: pubDate,
        description: description.substring(0, 500),
        source: 'edsurge',
        signal_type: 'trend'
      }
    });
  }
}

return results.length > 0 ? results : [{ json: { title: 'No items', link: '', source: 'edsurge', signal_type: 'trend' } }];

